/**
 * THE TITLE SCREEN'S PAINTING, AND THE HOUSE CREST
 *
 * A painted workshop at first light — landscape and a taller cut for portrait
 * windows — and the brass crest, keyed off its magenta ground. The title itself
 * is typeset over the painting in the game's own faces, never drawn into it: a
 * generator cannot letter, and type baked into a picture cannot be translated,
 * cannot reflow and goes soft the moment the picture is scaled.
 *
 * WebP at 80 halves what the same scene costs as JPEG, and the page carries them
 * as data URIs because the published build's CSP blocks external images.
 */

export const KEY_ART = "data:image/webp;base64,";

export const KEY_ART_TALL = "data:image/webp;base64,";

